@njit(parallel=False)  # pragma: no cover
def _get_radial_sum(dt, bins, bin_size, autocorr):
    radial_sum = np.zeros_like(bins[:-1], dtype=np.float64)
    for i, r in enumerate(bins[:-1]):
        mask = (dt <= r) * (dt > (r - bin_size[i]))
        # The autocorrelation is a real-valued (floating point) quantity, so it
        # must be accumulated in floating point.  Only the number of voxels in
        # the shell is an integer count.
        radial_sum[i] = np.sum(np.ravel(autocorr)[np.ravel(mask)]) / np.sum(
            mask, dtype=np.int64
        )
    return radial_sum
